mkitem!{mkstruct!{# [doc = " A priority queue implemented with a binary heap."] # [doc = ""] # [doc = " This will be a max-heap."] # [doc = ""] # [doc = " It is a logic error for an item to be modified in such a way that the"] # [doc = " item's ordering relative to any other item, as determined by the [`Ord`]"] # [doc = " trait, changes while it is in the heap. This is normally only possible"] # [doc = " through interior mutability, global state, I/O, or unsafe code. The"] # [doc = " behavior resulting from such a logic error is not specified, but will"] # [doc = " be encapsulated to the `BinaryHeap` that observed the logic error and not"] # [doc = " result in undefined behavior. This could include panics, incorrect results,"] # [doc = " aborts, memory leaks, and non-termination."] # [doc = ""] # [doc = " As long as no elements change their relative order while being in the heap"] # [doc = " as described above, the API of `BinaryHeap` guarantees that the heap"] # [doc = " invariant remains intact i.e. its methods all behave as documented. For"] # [doc = " example if a method is documented as iterating in sorted order, that's"] # [doc = " guaranteed to work as long as elements in the heap have not changed order,"] # [doc = " even in the presence of closures getting unwinded out of, iterators getting"] # [doc = " leaked, and similar foolishness."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use std::collections::BinaryHeap;"] # [doc = ""] # [doc = " // Type inference lets us omit an explicit type signature (which"] # [doc = " // would be `BinaryHeap<i32>` in this example)."] # [doc = " let mut heap = BinaryHeap::new();"] # [doc = ""] # [doc = " // We can use peek to look at the next item in the heap. In this case,"] # [doc = " // there's no items in there yet so we get None."] # [doc = " assert_eq!(heap.peek(), None);"] # [doc = ""] # [doc = " // Let's add some scores..."] # [doc = " heap.push(1);"] # [doc = " heap.push(5);"] # [doc = " heap.push(2);"] # [doc = ""] # [doc = " // Now peek shows the most important item in the heap."] # [doc = " assert_eq!(heap.peek(), Some(&5));"] # [doc = ""] # [doc = " // We can check the length of a heap."] # [doc = " assert_eq!(heap.len(), 3);"] # [doc = ""] # [doc = " // We can iterate over the items in the heap, although they are returned in"] # [doc = " // a random order."] # [doc = " for x in &heap {"] # [doc = "     println!(\"{x}\");"] # [doc = " }"] # [doc = ""] # [doc = " // If we instead pop these scores, they should come back in order."] # [doc = " assert_eq!(heap.pop(), Some(5));"] # [doc = " assert_eq!(heap.pop(), Some(2));"] # [doc = " assert_eq!(heap.pop(), Some(1));"] # [doc = " assert_eq!(heap.pop(), None);"] # [doc = ""] # [doc = " // We can clear the heap of any remaining items."] # [doc = " heap.clear();"] # [doc = ""] # [doc = " // The heap should now be empty."] # [doc = " assert!(heap.is_empty())"] # [doc = " ```"] # [doc = ""] # [doc = " A `BinaryHeap` with a known list of items can be initialized from an array:"] # [doc = ""] # [doc = " ```"] # [doc = " use std::collections::BinaryHeap;"] # [doc = ""] # [doc = " let heap = BinaryHeap::from([1, 5, 2]);"] # [doc = " ```"] # [doc = ""] # [doc = " ## Min-heap"] # [doc = ""] # [doc = " Either [`core::cmp::Reverse`] or a custom [`Ord`] implementation can be used to"] # [doc = " make `BinaryHeap` a min-heap. This makes `heap.pop()` return the smallest"] # [doc = " value instead of the greatest one."] # [doc = ""] # [doc = " ```"] # [doc = " use std::collections::BinaryHeap;"] # [doc = " use std::cmp::Reverse;"] # [doc = ""] # [doc = " let mut heap = BinaryHeap::new();"] # [doc = ""] # [doc = " // Wrap values in `Reverse`"] # [doc = " heap.push(Reverse(1));"] # [doc = " heap.push(Reverse(5));"] # [doc = " heap.push(Reverse(2));"] # [doc = ""] # [doc = " // If we pop these scores now, they should come back in the reverse order."] # [doc = " assert_eq!(heap.pop(), Some(Reverse(1)));"] # [doc = " assert_eq!(heap.pop(), Some(Reverse(2)));"] # [doc = " assert_eq!(heap.pop(), Some(Reverse(5)));"] # [doc = " assert_eq!(heap.pop(), None);"] # [doc = " ```"] # [doc = ""] # [doc = " # Time complexity"] # [doc = ""] # [doc = " | [push]  | [pop]         | [peek]/[peek\\_mut] |"] # [doc = " |---------|---------------|--------------------|"] # [doc = " | *O*(1)~ | *O*(log(*n*)) | *O*(1)             |"] # [doc = ""] # [doc = " The value for `push` is an expected cost; the method documentation gives a"] # [doc = " more detailed analysis."] # [doc = ""] # [doc = " [`core::cmp::Reverse`]: core::cmp::Reverse"] # [doc = " [`Cell`]: core::cell::Cell"] # [doc = " [`RefCell`]: core::cell::RefCell"] # [doc = " [push]: BinaryHeap::push"] # [doc = " [pop]: BinaryHeap::pop"] # [doc = " [peek]: BinaryHeap::peek"] # [doc = " [peek\\_mut]: BinaryHeap::peek_mut"] # [stable (feature = "rust1" , since = "1.0.0")] # [cfg_attr (not (test) , rustc_diagnostic_item = "BinaryHeap")] pub struct BinaryHeap < T , # [unstable (feature = "allocator_api" , issue = "32838")] A : Allocator = Global , > { data : Vec < T , A > , }}}
mkitem!{mkstruct!{# [doc = " Structure wrapping a mutable reference to the greatest item on a"] # [doc = " `BinaryHeap`."] # [doc = ""] # [doc = " This `struct` is created by the [`peek_mut`] method on [`BinaryHeap`]. See"] # [doc = " its documentation for more."] # [doc = ""] # [doc = " [`peek_mut`]: BinaryHeap::peek_mut"] # [stable (feature = "binary_heap_peek_mut" , since = "1.12.0")] pub struct PeekMut < 'a , T : 'a + Ord , # [unstable (feature = "allocator_api" , issue = "32838")] A : Allocator = Global , > { heap : & 'a mut BinaryHeap < T , A > , original_len : Option < NonZero < usize > > , }}}
mkitem!{mkimpl!{# [stable (feature = "collection_debug" , since = "1.17.0")] impl < T : Ord + fmt :: Debug , A : Allocator > fmt :: Debug for PeekMut < '_ , T , A > { fn fmt (& self , f : & mut fmt :: Formatter < '_ >) -> fmt :: Result { f . debug_tuple ("PeekMut") . field (& self . heap . data [0]) . finish () } }}}
mkitem!{mkimpl!{# [stable (feature = "binary_heap_peek_mut" , since = "1.12.0")] impl < T : Ord , A : Allocator > Drop for PeekMut < '_ , T , A > { fn drop (& mut self) { if let Some (original_len) = self . original_len { unsafe { self . heap . data . set_len (original_len . get ()) } ; unsafe { self . heap . sift_down (0) } ; } } }}}
mkitem!{mkimpl!{# [stable (feature = "binary_heap_peek_mut" , since = "1.12.0")] impl < T : Ord , A : Allocator > Deref for PeekMut < '_ , T , A > { type Target = T ; fn deref (& self) -> & T { debug_assert ! (! self . heap . is_empty ()) ; unsafe { self . heap . data . get_unchecked (0) } } }}}
mkitem!{mkimpl!{# [stable (feature = "binary_heap_peek_mut" , since = "1.12.0")] impl < T : Ord , A : Allocator > DerefMut for PeekMut < '_ , T , A > { fn deref_mut (& mut self) -> & mut T { debug_assert ! (! self . heap . is_empty ()) ; let len = self . heap . len () ; if len > 1 { unsafe { self . original_len = Some (NonZero :: new_unchecked (len)) ; self . heap . data . set_len (1) ; } } unsafe { self . heap . data . get_unchecked_mut (0) } } }}}
mkitem!{mkimpl!{impl < 'a , T : Ord , A : Allocator > PeekMut < 'a , T , A > { # [doc = " Sifts the current element to its new position."] # [doc = ""] # [doc = " Afterwards refers to the new element. Returns if the element changed."] # [doc = ""] # [doc = " ## Examples"] # [doc = ""] # [doc = " The condition can be used to upper bound all elements in the heap. When only few elements"] # [doc = " are affected, the heap's sort ensures this is faster than a reconstruction from the raw"] # [doc = " element list and requires no additional allocation."] # [doc = ""] # [doc = " ```"] # [doc = " #![feature(binary_heap_peek_mut_refresh)]"] # [doc = " use std::collections::BinaryHeap;"] # [doc = ""] # [doc = " let mut heap: BinaryHeap<u32> = (0..128).collect();"] # [doc = " let mut peek = heap.peek_mut().unwrap();"] # [doc = ""] # [doc = " loop {"] # [doc = "     *peek = 99;"] # [doc = ""] # [doc = "     if !peek.refresh() {"] # [doc = "         break;"] # [doc = "     }"] # [doc = " }"] # [doc = ""] # [doc = " // Post condition, this is now an upper bound."] # [doc = " assert!(*peek < 100);"] # [doc = " ```"] # [doc = ""] # [doc = " When the element remains the maximum after modification, the peek remains unchanged:"] # [doc = ""] # [doc = " ```"] # [doc = " #![feature(binary_heap_peek_mut_refresh)]"] # [doc = " use std::collections::BinaryHeap;"] # [doc = ""] # [doc = " let mut heap: BinaryHeap<u32> = [1, 2, 3].into();"] # [doc = " let mut peek = heap.peek_mut().unwrap();"] # [doc = ""] # [doc = " assert_eq!(*peek, 3);"] # [doc = " *peek = 42;"] # [doc = ""] # [doc = " // When we refresh, the peek is updated to the new maximum."] # [doc = " assert!(!peek.refresh(), \"42 is even larger than 3\");"] # [doc = " assert_eq!(*peek, 42);"] # [doc = " ```"] # [unstable (feature = "binary_heap_peek_mut_refresh" , issue = "138355")] # [must_use = "is equivalent to dropping and getting a new PeekMut except for return information"] pub fn refresh (& mut self) -> bool { if let Some (original_len) = self . original_len . take () { unsafe { self . heap . data . set_len (original_len . get ()) } ; (unsafe { self . heap . sift_down (0) }) != 0 } else { false } } # [doc = " Removes the peeked value from the heap and returns it."] # [stable (feature = "binary_heap_peek_mut_pop" , since = "1.18.0")] pub fn pop (mut this : PeekMut < 'a , T , A >) -> T { if let Some (original_len) = this . original_len . take () { unsafe { this . heap . data . set_len (original_len . get ()) } ; } unsafe { this . heap . pop () . unwrap_unchecked () } } }}}
mkitem!{mkimpl!{# [stable (feature = "rust1" , since = "1.0.0")] impl < T : Clone , A : Allocator + Clone > Clone for BinaryHeap < T , A > { fn clone (& self) -> Self { BinaryHeap { data : self . data . clone () } } # [doc = " Overwrites the contents of `self` with a clone of the contents of `source`."] # [doc = ""] # [doc = " This method is preferred over simply assigning `source.clone()` to `self`,"] # [doc = " as it avoids reallocation if possible."] # [doc = ""] # [doc = " See [`Vec::clone_from()`] for more details."] fn clone_from (& mut self , source : & Self) { self . data . clone_from (& source . data) ; } }}}
